# -*- coding: utf-8 -*-
"""
Shanghai Station dual-panel choropleth from embedded screenshot-inferred data
============================================================================

这版脚本已经把你给的 PPT 截图中的蓝紫色 join_count 分级，反推成了内置栅格数据。
运行时不再需要 reference_slide.png。

核心逻辑：
1. 加载 / 下载上海市边界和内部行政边界 GeoJSON；
2. 将每个行政单元投影到内置的截图反推栅格上；
3. 通过像素多数值反推出该行政单元的 join_count 分级；
4. 输出左右双图、GeoJSON 和 CSV。

重要说明：
- 截图只能反推颜色分级，不能恢复原始精确整数。
- 输出的 join_count_*_est 是区间代表值，不是原始统计值。
- 如果你有真实 OD / join_count 表，应优先用真实表 merge 替换这些估计值。

依赖：
pip install osmnx geopandas shapely pyproj matplotlib pandas numpy pillow requests

输出：
output/shanghai_station_join_embedded_estimated.geojson
output/shanghai_station_join_embedded_estimated.csv
output/shanghai_station_dual_map_embedded_v3.png
output/shanghai_station_dual_map_embedded_v3.pdf
"""

from pathlib import Path
import warnings
warnings.filterwarnings("ignore")

import base64
import zlib
import numpy as np
import pandas as pd
import geopandas as gpd
import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
from matplotlib import rcParams
from PIL import Image, ImageDraw, ImageFilter
from shapely.geometry import Point, Polygon, MultiPolygon

try:
    import osmnx as ox
except Exception:
    ox = None


# ============================================================
# 0. Paths
# ============================================================
ROOT = Path(".")
DATA_DIR = ROOT / "data"
OUT_DIR = ROOT / "output"
DATA_DIR.mkdir(exist_ok=True)
OUT_DIR.mkdir(exist_ok=True)

CITY_GEOJSON = DATA_DIR / "shanghai_city_osm.geojson"
ADMIN_GEOJSON = DATA_DIR / "shanghai_admin_osm.geojson"

STATION_LON = 121.4557
STATION_LAT = 31.2496
METRIC_CRS = "EPSG:32651"


# ============================================================
# 1. Screenshot-inferred data, embedded directly in this script
# ============================================================
JOIN_LABELS = ["0", "1", "2", "3", "4-5", "6-7", "8-13", "14-20", "21-30"]
JOIN_COLORS = [
    "#edf1f2",  # 0
    "#dbe7ef",  # 1
    "#b8cfe2",  # 2
    "#92b2d5",  # 3
    "#848fcb",  # 4-5
    "#9b74c8",  # 6-7
    "#9a43ae",  # 8-13
    "#9b168f",  # 14-20
    "#5f005c",  # 21-30
]
JOIN_COLOR_MAP = dict(zip(JOIN_LABELS, JOIN_COLORS))

CLASS_TO_RANGE = {
    "0": (0, 0),
    "1": (1, 1),
    "2": (2, 2),
    "3": (3, 3),
    "4-5": (4, 5),
    "6-7": (6, 7),
    "8-13": (8, 13),
    "14-20": (14, 20),
    "21-30": (21, 30),
}
CLASS_TO_REP = {
    "0": 0.0,
    "1": 1.0,
    "2": 2.0,
    "3": 3.0,
    "4-5": 4.5,
    "6-7": 6.5,
    "8-13": 10.5,
    "14-20": 17.0,
    "21-30": 25.5,
}

# 这些栅格来自你的截图：
# 左图 0812_9：大致裁切框 x=25..625, y=300..975
# 右图 0812_19：大致裁切框 x=735..1365, y=300..975
# 每个像素值是 0..8，对应 JOIN_LABELS。
# 使用 zlib + base64 压缩，避免运行时再读取截图。
EMBEDDED_RASTERS = {
    "am": {
        "source_panel": "0812_9",
        "meaning": "目的地为片区内（早高峰）",
        "shape": (675, 600),
        "data": """""",
    },
    "pm": {
        "source_panel": "0812_19",
        "meaning": "出发地为片区内（晚高峰）",
        "shape": (675, 630),
        "data": """""",
    },
}

# 栅格与地理坐标之间的线性映射 padding。
# 如果你发现反推结果整体偏移，可以微调这两个值。
MAP_PAD_FRAC_X = 0.03
MAP_PAD_FRAC_Y = 0.03

# 面状行政单元采样前做轻微腐蚀，避开边线抗锯齿。
MASK_ERODE_SIZE = 5
MIN_PIXELS_FOR_MODE = 10


# ============================================================
# 2. Utility functions
# ============================================================
def ensure_cn_font():
    candidates = [
        "Noto Sans CJK SC", "Source Han Sans SC", "Microsoft YaHei",
        "SimHei", "PingFang SC", "Arial Unicode MS"
    ]
    rcParams["font.sans-serif"] = candidates + rcParams.get("font.sans-serif", [])
    rcParams["axes.unicode_minus"] = False


def decode_raster(name: str) -> np.ndarray:
    obj = EMBEDDED_RASTERS[name]
    raw = zlib.decompress(base64.b64decode(obj["data"]))
    arr = np.frombuffer(raw, dtype=np.uint8).reshape(obj["shape"])
    return arr


def add_join_value_columns(gdf: gpd.GeoDataFrame, suffix: str) -> gpd.GeoDataFrame:
    class_col = f"join_class_{suffix}"
    gdf[f"join_count_{suffix}_lb"] = gdf[class_col].map(lambda x: CLASS_TO_RANGE.get(x, (np.nan, np.nan))[0])
    gdf[f"join_count_{suffix}_ub"] = gdf[class_col].map(lambda x: CLASS_TO_RANGE.get(x, (np.nan, np.nan))[1])
    gdf[f"join_count_{suffix}_est"] = gdf[class_col].map(lambda x: CLASS_TO_REP.get(x, np.nan))
    return gdf


def geo_to_raster_xy(x, y, width, height, bounds):
    minx, miny, maxx, maxy = bounds
    dx = maxx - minx
    dy = maxy - miny
    minx = minx - dx * MAP_PAD_FRAC_X
    maxx = maxx + dx * MAP_PAD_FRAC_X
    miny = miny - dy * MAP_PAD_FRAC_Y
    maxy = maxy + dy * MAP_PAD_FRAC_Y

    px = (x - minx) / (maxx - minx) * width
    py = height - (y - miny) / (maxy - miny) * height
    return px, py


def polygon_to_mask(geom, width, height, bounds):
    mask_img = Image.new("L", (width, height), 0)
    draw = ImageDraw.Draw(mask_img)

    def tf(x, y):
        return geo_to_raster_xy(x, y, width, height, bounds)

    def draw_poly(poly):
        ext = [tf(x, y) for x, y in np.asarray(poly.exterior.coords)]
        draw.polygon(ext, outline=255, fill=255)
        for ring in poly.interiors:
            hole = [tf(x, y) for x, y in np.asarray(ring.coords)]
            draw.polygon(hole, outline=0, fill=0)

    if isinstance(geom, Polygon):
        draw_poly(geom)
    elif isinstance(geom, MultiPolygon):
        for poly in geom.geoms:
            draw_poly(poly)

    if MASK_ERODE_SIZE and MASK_ERODE_SIZE > 1:
        mask_img = mask_img.filter(ImageFilter.MinFilter(MASK_ERODE_SIZE))

    return np.asarray(mask_img) > 0


def sample_polygon_class(geom, raster, bounds):
    height, width = raster.shape
    mask = polygon_to_mask(geom, width, height, bounds)
    vals = raster[mask]

    # 很小的 polygon 可能采样不到足够像素，改用 centroid 采样。
    if len(vals) < MIN_PIXELS_FOR_MODE:
        c = geom.representative_point()
        px, py = geo_to_raster_xy(c.x, c.y, width, height, bounds)
        xi = int(np.clip(round(px), 0, width - 1))
        yi = int(np.clip(round(py), 0, height - 1))
        idx = int(raster[yi, xi])
        return JOIN_LABELS[idx], 1, 1.0, "centroid"

    counts = np.bincount(vals.astype(int), minlength=len(JOIN_LABELS))
    idx = int(np.argmax(counts))
    mode_count = int(counts[idx])
    mode_share = float(mode_count / max(len(vals), 1))

    if mode_share >= 0.70:
        confidence = "high"
    elif mode_share >= 0.50:
        confidence = "medium"
    else:
        confidence = "low"

    return JOIN_LABELS[idx], int(len(vals)), mode_share, confidence


# ============================================================
# 3. GeoJSON / OSM loading
# ============================================================
def load_or_download_boundaries():
    if CITY_GEOJSON.exists():
        city = gpd.read_file(CITY_GEOJSON)
    else:
        if ox is None:
            raise RuntimeError(
                "本地没有 data/shanghai_city_osm.geojson，且 osmnx 未安装。\n"
                "请先安装 osmnx，或手动放入上海市边界 GeoJSON。"
            )
        print("Downloading Shanghai municipal boundary from OSM/Nominatim...")
        city = ox.geocode_to_gdf("Shanghai, China")
        city = city[["display_name", "geometry"]].to_crs("EPSG:4326")
        city.to_file(CITY_GEOJSON, driver="GeoJSON")

    city = city.to_crs("EPSG:4326")
    city_poly = city.geometry.iloc[0]

    if ADMIN_GEOJSON.exists():
        admin = gpd.read_file(ADMIN_GEOJSON)
    else:
        if ox is None:
            raise RuntimeError(
                "本地没有 data/shanghai_admin_osm.geojson，且 osmnx 未安装。\n"
                "请先安装 osmnx，或手动放入上海行政边界 GeoJSON。"
            )
        print("Downloading administrative boundaries from OSM...")
        tags = {"boundary": "administrative"}
        admin = ox.features_from_polygon(city_poly, tags=tags).reset_index()
        admin = admin[admin.geometry.geom_type.isin(["Polygon", "MultiPolygon"])].copy()

        keep_cols = [
            c for c in [
                "osmid", "name", "name:zh", "name:en", "admin_level",
                "boundary", "geometry"
            ] if c in admin.columns
        ]
        admin = admin[keep_cols].copy()
        admin["admin_level"] = pd.to_numeric(admin.get("admin_level"), errors="coerce")
        admin = admin[admin["admin_level"].isin([6, 7, 8, 9, 10])].copy()

        admin["geom_wkb"] = admin.geometry.apply(lambda g: g.wkb_hex)
        admin = admin.drop_duplicates(subset=["name", "admin_level", "geom_wkb"]).drop(columns="geom_wkb")

        admin = admin.set_crs("EPSG:4326", allow_override=True)
        admin = gpd.clip(admin, city[["geometry"]])
        admin.to_file(ADMIN_GEOJSON, driver="GeoJSON")

    admin = admin.to_crs("EPSG:4326")
    admin = admin[~admin.geometry.is_empty & admin.geometry.notna()].copy()
    return city, admin


# ============================================================
# 4. Fill data from embedded raster
# ============================================================
def fill_inferred_join_data(city, admin):
    bounds = city.total_bounds
    out = admin.copy()

    for suffix in ["am", "pm"]:
        raster = decode_raster(suffix)
        labels = []
        pixel_counts = []
        mode_shares = []
        confs = []

        for geom in out.geometry:
            lab, npx, share, conf = sample_polygon_class(geom, raster, bounds)
            labels.append(lab)
            pixel_counts.append(npx)
            mode_shares.append(share)
            confs.append(conf)

        out[f"join_class_{suffix}"] = labels
        out[f"join_infer_{suffix}_pixels"] = pixel_counts
        out[f"join_infer_{suffix}_mode_share"] = mode_shares
        out[f"join_infer_{suffix}_confidence"] = confs
        out[f"join_infer_{suffix}_source"] = EMBEDDED_RASTERS[suffix]["source_panel"]

        out = add_join_value_columns(out, suffix)

    return out


# ============================================================
# 5. Plotting
# ============================================================
def station_gdf():
    return gpd.GeoDataFrame(
        {"name": ["Shanghai Railway Station"]},
        geometry=[Point(STATION_LON, STATION_LAT)],
        crs="EPSG:4326",
    )


def station_zoom_geom(radius_km=5.0):
    s = station_gdf().to_crs(METRIC_CRS)
    buf = s.buffer(radius_km * 1000).iloc[0]
    return gpd.GeoSeries([buf], crs=METRIC_CRS).to_crs("EPSG:4326").iloc[0]


def draw_map(ax, city, admin, suffix, title, zoom_geom=None):
    class_col = f"join_class_{suffix}"
    g = admin.copy()
    g["fill"] = g[class_col].map(JOIN_COLOR_MAP).fillna(JOIN_COLOR_MAP["0"])

    city.plot(ax=ax, facecolor="#f7fafb", edgecolor="#c4ccd0", linewidth=0.75, zorder=0)
    g.plot(ax=ax, color=g["fill"], edgecolor="#d4dce0", linewidth=0.35, zorder=1)

    if "admin_level" in g.columns:
        higher = g[g["admin_level"].isin([6, 7])]
        if len(higher) > 0:
            higher.boundary.plot(ax=ax, color="#c4cdd1", linewidth=0.60, zorder=2)

    station_gdf().plot(ax=ax, color="#333333", markersize=9, zorder=4)

    if zoom_geom is not None:
        minx, miny, maxx, maxy = zoom_geom.bounds
        pad_x = (maxx - minx) * 0.08
        pad_y = (maxy - miny) * 0.08
        ax.set_xlim(minx - pad_x, maxx + pad_x)
        ax.set_ylim(miny - pad_y, maxy + pad_y)
    else:
        minx, miny, maxx, maxy = city.total_bounds
        pad_x = (maxx - minx) * 0.03
        pad_y = (maxy - miny) * 0.03
        ax.set_xlim(minx - pad_x, maxx + pad_x)
        ax.set_ylim(miny - pad_y, maxy + pad_y)

    ax.set_aspect("equal")
    ax.axis("off")
    if title:
        ax.set_title(title, fontsize=15, weight="bold", pad=8)


def render_dual(city, admin):
    ensure_cn_font()

    fig = plt.figure(figsize=(17.4, 10.0), dpi=220)
    fig.patch.set_facecolor("white")

    ax1 = fig.add_axes([0.035, 0.16, 0.40, 0.68])
    ax2 = fig.add_axes([0.455, 0.16, 0.40, 0.68])
    ax1_in = fig.add_axes([0.305, 0.065, 0.12, 0.17])
    ax2_in = fig.add_axes([0.725, 0.065, 0.12, 0.17])

    draw_map(ax1, city, admin, "am", "目的地为片区内（早高峰）")
    draw_map(ax2, city, admin, "pm", "出发地为片区内（晚高峰）")

    zoom = station_zoom_geom(radius_km=5.0)
    draw_map(ax1_in, city, admin, "am", "", zoom_geom=zoom)
    draw_map(ax2_in, city, admin, "pm", "", zoom_geom=zoom)

    ax1.text(0.02, -0.035, "0812_9", transform=ax1.transAxes, fontsize=12, color="#333333")
    ax2.text(0.02, -0.035, "0812_19", transform=ax2.transAxes, fontsize=12, color="#333333")

    legend_patches = [
        mpatches.Patch(facecolor=JOIN_COLOR_MAP[l], edgecolor="#8f8f8f", label=l)
        for l in JOIN_LABELS
    ]
    fig.legend(
        handles=legend_patches,
        title="join_count",
        bbox_to_anchor=(0.965, 0.12),
        loc="lower right",
        frameon=False,
        fontsize=10,
        title_fontsize=13,
    )

    fig.suptitle(
        "片区2：上海站｜职住分析（截图反推 join_count 版）",
        fontsize=20,
        weight="bold",
        y=0.965,
    )
    fig.text(
        0.5,
        0.925,
        "颜色和分级来自截图图例；每个行政单元通过内置截图栅格多数值采样反推，join_count_est 为区间代表值。",
        ha="center",
        va="center",
        fontsize=10.5,
        color="#555555",
    )

    out_png = OUT_DIR / "shanghai_station_dual_map_embedded_v3.png"
    out_pdf = OUT_DIR / "shanghai_station_dual_map_embedded_v3.pdf"
    fig.savefig(out_png, bbox_inches="tight", pad_inches=0.03)
    fig.savefig(out_pdf, bbox_inches="tight", pad_inches=0.03)
    plt.close(fig)
    print(f"Saved: {out_png}")
    print(f"Saved: {out_pdf}")


# ============================================================
# 6. Main
# ============================================================
def main():
    city, admin = load_or_download_boundaries()
    print(f"Loaded admin polygons: {len(admin)}")

    admin_filled = fill_inferred_join_data(city, admin)

    out_geojson = OUT_DIR / "shanghai_station_join_embedded_estimated.geojson"
    out_csv = OUT_DIR / "shanghai_station_join_embedded_estimated.csv"
    admin_filled.to_file(out_geojson, driver="GeoJSON")
    admin_filled.drop(columns="geometry").to_csv(out_csv, index=False, encoding="utf-8-sig")
    print(f"Saved: {out_geojson}")
    print(f"Saved: {out_csv}")

    for suffix in ["am", "pm"]:
        col = f"join_class_{suffix}"
        print(f"\n{col} distribution:")
        print(admin_filled[col].value_counts().reindex(JOIN_LABELS).fillna(0).astype(int))

    render_dual(city, admin_filled)


if __name__ == "__main__":
    main()
